// Topic-wise study (সূচিপত্র): a chapter's topics, and one page per topic that gathers that
// topic's part of every section — MCQ, CQ, ক, খ, concepts, formulas … — with its own progress.
// The topic → items map is generated by tools/build-toc.mjs into content/toc.json.

import { icon } from '../icons.js?v=202610230738';
import { esc, ring, bar, chapterEyebrow, chapterNo, pad2, sectionHue, emptyState } from '../components.js?v=202610230738';
import { isItemDone } from '../progress.js?v=202610230738';
import { itemCard } from './section.js?v=202610230738';
import { hasTopicGames } from '../gamedata.js?v=202610230738';

const bn = (s) => String(s).replace(/\d/g, (d) => '০১২৩৪৫৬৭৮৯'[d]);
const SHORT = { cq: 'CQ', concept: 'কনসেপ্ট', mistakes: 'ভুল', revision: 'রিভিশন', identification: 'শনাক্তকরণ' };

let toc = null;
export async function loadToc() {
  try {
    const r = await fetch('content/toc.json', { cache: 'no-cache' });
    toc = r.ok ? (await r.json()).chapters ?? {} : {};
  } catch {
    toc = {};
  }
}
export const tocOf = (chapterId) => toc?.[chapterId] ?? null;

// Which section blocks are open survives a redraw (e.g. after "Mark as done").
const openBlocks = new Set();
document.addEventListener('toggle', (e) => {
  const k = e.target?.dataset?.tpKey;
  if (!k) return;
  if (e.target.open) openBlocks.add(k);
  else openBlocks.delete(k);
}, true);

function stats(ids) {
  const done = ids.filter((id) => isItemDone(id)).length;
  return { done, total: ids.length, pct: ids.length ? Math.round((done / ids.length) * 100) : 0 };
}

function groups(ch, ids) {
  const set = new Set(ids);
  return ch.sections
    .filter((s) => !s.computed)
    .map((sec) => ({ sec, items: sec.items.filter((it) => set.has(it.id)) }))
    .filter((g) => g.items.length);
}

const shortLabel = (sec) => SHORT[sec.type] ?? sec.label;

// Chapter page: the table of contents.
export function tocCard(ch) {
  const t = tocOf(ch.id);
  if (!t) return '';
  const rows = t.topics.map((tp, i) => {
    const s = stats(tp.items);
    const parts = groups(ch, tp.items).map((g) => `${shortLabel(g.sec)} ${bn(g.items.length)}`).join(' · ');
    return `<a class="toc-row tap rise ${s.pct === 100 ? 'done' : ''}" style="--i:${Math.min(i, 12)}" href="#/t/${esc(ch.id)}/${esc(tp.id)}">
        <span class="toc-no">${bn(pad2(i + 1))}</span>
        <span class="toc-body"><b>${esc(tp.name)}</b><small>${esc(parts)}</small>${bar(s.pct, 'bar-thin')}</span>
        <span class="toc-pct">${s.pct === 100 ? icon('check') : `${bn(s.pct)}%`}</span>${icon('chevron', 'cc-chev')}
      </a>`;
  }).join('');
  return `<section class="block toc-block"><div class="block-head"><h2>সূচিপত্র · টপিক অনুযায়ী</h2></div>
      <p class="muted small toc-help">প্রতিটা টপিকে সেই অংশের Notes, MCQ, CQ, ক, খ… সব এক জায়গায়। টপিকটা শেষ করলে ওই অংশের সব পড়া শেষ।</p>
      <div class="toc-list">${rows}</div></section>`;
}

// One topic.
export function topicView(model, chapterId, topicId) {
  const ch = model.byId.get(chapterId);
  const t = tocOf(chapterId);
  if (ch?.level !== 'chapter' || !t) return null;
  const k = t.topics.findIndex((x) => x.id === topicId);
  if (k < 0) return null;
  const tp = t.topics[k];
  const s = stats(tp.items);
  const prev = t.topics[k - 1];
  const next = t.topics[k + 1];

  blocks.clear();
  const block = (g, key, i) => {
    blocks.set(key, g);
    const gs = stats(g.items.map((it) => it.id));
    const open = openBlocks.has(key);
    return `<details class="tp-block rise" style="--i:${Math.min(i, 10)}" data-tp-key="${esc(key)}" ${open ? 'open' : ''}>
        <summary><span class="sec-icon sm hue-${sectionHue(g.sec.type)}">${icon(g.sec.type)}</span>
          <span class="tp-name"><b>${esc(g.sec.label)}</b><small>${bn(gs.done)}/${bn(gs.total)} শেষ</small></span>
          ${gs.pct === 100 ? `<span class="ok-tag">${icon('check')}</span>` : `<span class="tp-pct">${bn(gs.pct)}%</span>`}${icon('down', 'fold-chev')}</summary>
        <div class="items">${open ? g.items.map((it, n) => itemCard(it, g.sec, n)).join('') : ''}</div>
      </details>`;
  };
  const list = groups(ch, tp.items);
  const wide = groups(ch, t.general);
  const body = list.length
    ? list.map((g, i) => block(g, `${ch.id}/${tp.id}/${g.sec.type}`, i + 1)).join('')
    : emptyState({ iconName: 'layers', title: 'এই টপিকে এখনো কিছু নেই', text: 'কনটেন্ট যোগ হলে এখানে দেখা যাবে।' });
  const wideHtml = `<section class="block"><div class="block-head"><h2>পুরো অধ্যায়ের জন্য</h2></div>
        <a class="tp-link tap" href="#/mm/${esc(ch.id)}">${icon('map')}<span>মাইন্ড ম্যাপ</span>${icon('chevron', 'cc-chev')}</a>
        ${wide.map((g, i) => block(g, `${ch.id}/general/${g.sec.type}`, i)).join('')}</section>`;

  return {
    nav: 'study',
    title: `টপিক ${bn(k + 1)}/${bn(t.topics.length)}`,
    back: `#/c/${ch.id}`,
    crumbs: [[ch.subject.name, `#/s/${ch.subject.id}`], [chapterNo(ch) != null ? `Ch ${pad2(chapterNo(ch))}` : ch.name, `#/c/${ch.id}`], [`টপিক ${bn(k + 1)}`, `#/t/${ch.id}/${tp.id}`]],
    accent: ch.subject.accent,
    visit: { chapterId: ch.id },
    html: `<header class="tp-hero rise">
        <div><p class="eyebrow">${esc(ch.subject.name)} · ${esc(chapterEyebrow(ch))} · টপিক ${bn(k + 1)}/${bn(t.topics.length)}</p>
          <h1 class="bn">${esc(tp.name)}</h1>
          <p class="muted small">${bn(s.done)}/${bn(s.total)}টি শেষ · ${esc(ch.name)}</p></div>
        ${ring(s.pct, { size: 72, stroke: 6 })}
      </header>
      ${s.pct === 100 ? `<p class="tp-done rise">${icon('check')}<span>এই টপিক পুরো শেষ! পরের টপিকে যাও।</span></p>` : ''}
      <div class="row-btns tp-actions">
        <button class="btn tap" data-hf-topic="${esc(ch.id)}/${esc(tp.id)}">${icon('speaker')}<span>ইয়ারবাডে শোনো</span></button>
        ${hasTopicGames(ch.id, tp.id) ? `<a class="btn tap gm-entry" href="#/games/${esc(ch.id)}/${esc(tp.id)}">🎮<span>এই টপিকে গেম</span></a>` : ''}
        <button class="btn tap" data-ex-quick="${esc(ch.id)}/${esc(tp.id)}">${icon('mcq')}<span>এই টপিকে পরীক্ষা</span></button>
        <a class="btn tap" href="#/cards/${esc(ch.id)}/${esc(tp.id)}">${icon('concept')}<span>ফ্ল্যাশকার্ড</span></a>
      </div>
      <p class="muted small tp-help">প্রতিটা অংশে চাপ দিলে খুলবে। পড়া শেষ হলে "Mark as done" দাও — টপিকের প্রগ্রেস বাড়বে।</p>
      <div class="tp-blocks">${body}</div>
      ${wideHtml}
      <nav class="pager" aria-label="Topic navigation">
        ${prev ? `<a class="tap" href="#/t/${esc(ch.id)}/${esc(prev.id)}">${icon('back')}<span><small>আগের টপিক</small>${esc(prev.name)}</span></a>` : `<a class="tap" href="#/c/${esc(ch.id)}">${icon('back')}<span><small>অধ্যায়</small>${esc(ch.name)}</span></a>`}
        ${next ? `<a class="tap next" href="#/t/${esc(ch.id)}/${esc(next.id)}"><span><small>পরের টপিক</small>${esc(next.name)}</span>${icon('chevron')}</a>` : '<span></span>'}
      </nav>`,
  };
}

// Blocks render their cards only when opened, so a 200-MCQ topic stays light.
const blocks = new Map();
document.addEventListener('toggle', (e) => {
  const d = e.target;
  const g = d?.dataset?.tpKey && d.open && blocks.get(d.dataset.tpKey);
  const box = g && d.querySelector('.items');
  if (box && !box.childElementCount) box.innerHTML = g.items.map((it, n) => itemCard(it, g.sec, n)).join('');
}, true);
